// @ts-nocheck -- exercises the still-untyped port (and, for fixtures, the legacy JS) through one code path.
// Golden tests for the core client (shared/core/restreamer.ts) against a fake datarhei-core.
//
// The fixtures in shared/__fixtures__/core were generated by running THIS file against the untouched
// legacy implementation (bun scripts/legacy/gen-core-fixtures.ts), so a green
// run here means the port produces the same requests/process configs as legacy for these scenarios.
import { afterAll, afterEach, beforeAll, describe, expect, test } from 'bun:test';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';

import type { CoreOptions } from '../__fixtures__/core/fake-core';
import {
	ADDRESS,
	b64,
	jwt,
	ACCESS_TOKEN,
	REFRESH_TOKEN,
	json,
	notFound,
	skillsResponse,
	configResponse,
	localAssets,
	Recorded,
	FakeCore,
} from '../__fixtures__/core/fake-core';

const LEGACY = process.env.RESTREAMER_IMPL === 'legacy';
const UPDATE = process.env.UPDATE_FIXTURES === '1';
const FIXTURES = join(import.meta.dir, '..', '__fixtures__', 'core');

// What every legacy build sets (Dockerfile, workflows); prefix of the UI's own static assets.
process.env.PUBLIC_URL = './';

const base = LEGACY ? '../../legacy/src/utils' : '.';
const Restreamer = (await import(`${base}/restreamer`)).default;
const Storage = await import(`${base}/storage`);
const { anonymize, anonymize_url } = await import(`${base}/anonymizer`);

const CHANNEL = '00000000-0000-4000-8000-000000000001';
const EGRESS = '00000000-0000-4000-8000-000000000002';

// ---------------------------------------------------------------------------------------------
// Fixtures

function expectFixture(name: string, value: unknown) {
	const file = join(FIXTURES, name + '.json');

	if (UPDATE) {
		mkdirSync(dirname(file), { recursive: true });
		writeFileSync(file, JSON.stringify(value, null, '\t') + '\n');
		return;
	}

	expect(existsSync(file)).toBe(true);
	const expected = JSON.parse(readFileSync(file, 'utf8'));

	// Readable diff first, then the compact form which is also sensitive to key order.
	expect(JSON.parse(JSON.stringify(value))).toEqual(expected);
	expect(JSON.stringify(value)).toBe(JSON.stringify(expected));
}

// ---------------------------------------------------------------------------------------------
// Client helpers

const clients: any[] = [];

function newClient(address = ADDRESS) {
	const client = new Restreamer(address);
	clients.push(client);
	return client;
}

// Replaces the random channel/egress UUIDs so that the output is stable.
function normalize<T>(value: T, ids: Record<string, string>): T {
	let text = JSON.stringify(value);
	for (const [id, replacement] of Object.entries(ids)) {
		text = text.replaceAll(id, replacement);
	}

	return JSON.parse(text);
}

async function connect(opts: Partial<CoreOptions> = {}) {
	const core = new FakeCore(opts);
	core.install();

	const client = newClient();
	const events: any[] = [];
	client.AddListener((event: any) => events.push(event));

	expect(await client.Validate()).toBe(true);
	expect(client.IsConnected()).toBe(false);
	expect(await client.Login('admin', 'secret')).toBe(true);
	expect(client.IsConnected()).toBe(true);

	const channelid: string = client.GetCurrentChannelID();
	core.sessionReference = channelid;

	return { core, client, events, channelid, ids: { [channelid]: CHANNEL } as Record<string, string> };
}

const realFetch = globalThis.fetch;
const realConsoleError = console.error;

beforeAll(() => {
	// The API client logs every non-2xx response; expected 404s (upsert, missing metadata) would flood the output.
	console.error = () => {};
});

afterEach(() => {
	for (const client of clients.splice(0)) {
		clearTimeout(client.refresh);
		clearTimeout(client.updates);
	}
});

afterAll(() => {
	globalThis.fetch = realFetch;
	console.error = realConsoleError;
});

// ---------------------------------------------------------------------------------------------
// Scenario inputs (what legacy/src/views/Edit and .../Publication hand to the client)

const merge = (a: any, b: any): any => {
	const out = JSON.parse(JSON.stringify(a));
	for (const key in b) {
		out[key] = b[key] && typeof b[key] === 'object' && !Array.isArray(b[key]) ? merge(out[key] ?? {}, b[key]) : b[key];
	}

	return out;
};

// Defaults of the ingest metadata (legacy/src/utils/metadata.js: defaultIngestMetadata.control)
const ingestControl = (overrides: any = {}) =>
	merge(
		{
			hls: { lhls: false, segmentDuration: 2, listSize: 6, cleanup: true, version: 3, storage: 'memfs', master_playlist: true },
			rtmp: { enable: false },
			srt: { enable: false },
			process: { autostart: true, reconnect: true, delay: 15, staleTimeout: 30, low_delay: false },
			snapshot: { enable: true, interval: 60 },
			limits: { cpu_usage: 0, memory_mbytes: 0, waitfor_seconds: 5 },
		},
		overrides,
	);

// Defaults of the egress metadata (defaultEgressMetadata.control)
const egressControl = (overrides: any = {}) =>
	merge(
		{
			process: { autostart: false, reconnect: true, delay: 15, staleTimeout: 30 },
			source: { source: 'hls+memfs' },
			limits: { cpu_usage: 0, memory_mbytes: 0, waitfor_seconds: 5 },
		},
		overrides,
	);

// A pulled RTSP camera with H.264 video and 48 kHz AAC audio. Numbers on purpose: the client stringifies options.
const ingestInputs = () => [
	{
		address: 'rtsp://user:pass@camera.example.com:554/stream',
		options: [
			'-fflags',
			'+genpts',
			'-thread_queue_size',
			512,
			'-probesize',
			5000000,
			'-analyzeduration',
			5000000,
			'-timeout',
			5000000,
			'-rtsp_transport',
			'tcp',
		],
	},
];

// As produced by M.createInputsOutputs for the 'copy' and 'aac' audio coders (the aac coder appends
// '-bsf:a aac_adtstoasc' when the source stream is AAC; aresample is the default audio filter graph).
const AUDIO = {
	copy: ['-map', '0:1', '-codec:a', 'copy'],
	aac: ['-map', '0:1', '-filter:a', 'aresample=osr=44100:ochl=stereo', '-codec:a', 'aac', '-b:a', '64k', '-shortest', '-bsf:a', 'aac_adtstoasc'],
};

const outputs = (audio: keyof typeof AUDIO, address = '') => [{ address, options: ['-map', '0:0', '-codec:v', 'copy', ...AUDIO[audio]] }];

const HLS = {
	hls3: { version: 3 },
	hls6: { version: 6 },
	hls7: { version: 7 },
	lhls: { lhls: true, version: 7 },
};

const RESTREAM = {
	none: { rtmp: { enable: false }, srt: { enable: false } },
	rtmp: { rtmp: { enable: true }, srt: { enable: false } },
	srt: { rtmp: { enable: false }, srt: { enable: true } },
	'rtmp+srt': { rtmp: { enable: true }, srt: { enable: true } },
};

